makeMtLab(document.getElementById("lab-l29"),{id:"l29",scenarios:[{"label": "Ví dụ: Hai sự kiện hợp lệ", "note": "Liền nhau, không chồng.", "steps": [{"t": "RUNNING 06:00–09:00", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\">INSERT 0 1<\/span><\/div>"}, {"t": "DOWN 09:00–09:40", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\">INSERT 0 1<\/span><\/div>", "ask": {"q": "[06:00, 09:00) và [09:00, 09:40) có chồng lấn không?", "o": ["Có, chung mốc 09:00", "Không, vì đầu phải mở"], "a": 1}}]}, {"label": "Lỗi: Sự kiện chồng lấn", "note": "Ràng buộc loại trừ.", "steps": [{"t": "IDLE 09:30–09:50", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\">ERROR:  conflicting key value violates exclusion constraint \"state_event_machine_id_period_excl\"<\/span><\/div>"}, {"t": "Đọc DETAIL", "html": "<p class=\"mt-calc\">Chồng với DOWN [09:00, 09:40)<\/p>"}]}, {"label": "Lỗi: Máy không tồn tại", "note": "Khóa ngoại.", "steps": [{"t": "machine_id = 'L1-M9'", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\">ERROR:  insert or update on table \"state_event\" violates foreign key constraint<\/span><\/div>"}, {"t": "Sửa", "html": "<p class=\"mt-calc\">Thêm máy vào bảng machine trước, hoặc sửa mã máy trong cấu hình collector<\/p>"}]}, {"label": "Lỗi: Trạng thái lạ", "note": "ENUM.", "steps": [{"t": "state = 'STOP'", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\">ERROR:  invalid input value for enum machine_state: \"STOP\"<\/span><\/div>"}, {"t": "Sửa", "html": "<p class=\"mt-calc\">Ánh xạ trạng thái PLC sang 4 giá trị chuẩn trong collector<\/p>"}]}, {"label": "Bẫy: Chỉ kiểm tra ở ứng dụng", "note": "Đường vào khác không bị kiểm tra.", "steps": [{"t": "Script nhập tay chèn sự kiện chồng", "html": "<p class=\"mt-calc\">Không có ràng buộc ở CSDL → lọt<\/p>"}, {"t": "Hậu quả", "html": "<p class=\"mt-calc\">Thời gian chạy bị đếm hai lần, A > 1<\/p>", "say": "<p>Ràng buộc CSDL là lớp phòng thủ cuối.<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l29"),"l29",[{"kind": "num", "t": "Khoảng thời gian", "d": "<p>Trả lời bằng số phút.<\/p>", "items": [{"q": "[09:00, 09:40) và [09:30, 09:50) chồng nhau bao nhiêu phút?", "a": 10, "unit": "phút"}, {"q": "[06:00, 09:00) và [09:00, 09:40) chồng nhau bao nhiêu phút?", "a": 0, "unit": "phút"}, {"q": "Sự kiện DOWN [09:00, 09:40) dài bao nhiêu phút?", "a": 40, "unit": "phút"}], "hints": ["Phần chung = min(kết thúc) − max(bắt đầu).", "Âm hoặc 0 thì không chồng."], "why": "09:40 − 09:30 = 10; 0; 40."}, {"kind": "pick", "t": "Ràng buộc nào chặn?", "d": "<p>Chọn ràng buộc chặn dữ liệu sai.<\/p>", "cats": ["Khóa ngoại", "ENUM", "Loại trừ", "CHECK"], "items": [{"q": "Sự kiện của máy chưa khai báo", "a": 0}, {"q": "Trạng thái 'RUN'", "a": 1}, {"q": "Hai sự kiện cùng máy chồng thời gian", "a": 2}, {"q": "Cổng PLC = 70 000", "a": 3}], "hints": ["Tham chiếu tới bảng khác: khóa ngoại.", "Khoảng chồng: loại trừ; giá trị ngoài miền: CHECK."], "why": "Máy lạ: FK; trạng thái lạ: ENUM; chồng lấn: EXCLUDE; cổng ngoài miền: CHECK."}, {"kind": "order", "t": "Collector gặp lỗi ràng buộc", "d": "<p>Sắp xếp.<\/p>", "items": ["INSERT sự kiện", "PostgreSQL trả lỗi ràng buộc", "Collector bắt lỗi, ghi log ERROR kèm dữ liệu", "Bỏ qua bản ghi sai, tiếp tục vòng đọc", "Kỹ sư đọc log và sửa cấu hình"], "hints": ["Không để một bản ghi sai làm dừng vòng đọc.", "Ghi log đủ để sửa."], "why": "INSERT → lỗi → log → tiếp tục → sửa."}]);
